import type { HookCallback } from "@anthropic-ai/claude-agent-sdk/core";

export class Watcher {
  readonly events: WatchEvent[] = []; // the last 200
  readonly errors = new Map<string, number>();
  readonly fileHashes = new Map<string, string[]>();
  readonly failing = new Set<string>();
  flatFor = 0;
  onTool: HookCallback = async (input) => { // registered for PostToolUse and PostToolUseFailure
    const ev = WatchEvent.of(input); // tool, normalized input hash, output hash, error signature, file hash
    this.events.push(ev);
    if (this.events.length > 200) this.events.shift();
    this.flatFor = this.progressed(ev) ? 0 : this.flatFor + 1;
    state.verdict = { flatFor: this.flatFor, loopKind: this.loopKind(ev), evidence: ev.evidence() }; // G3-36 acts on it
    return {};
  };

  progressed(ev: WatchEvent): boolean {
    const fixed = ev.isCheck && ev.passed && this.failing.has(ev.check); // a check that failed now passes
    if (ev.isCheck) this.failing[ev.passed ? "delete" : "add"](ev.check);
    return fixed || ev.todoCompleted || ev.firstRead; // or a plan item done, or a new fact
  }

  loopKind(ev: WatchEvent): string | null {
    const last = this.events.slice(-6);
    if (ev.error) this.errors.set(ev.error, (this.errors.get(ev.error) ?? 0) + 1);
    const undo = this.rememberFile(ev); // true when an edit brings a file back to an earlier state
    if (last.filter((e) => e.key === ev.key).length >= 3) return "same command, same result";
    if (ev.error && (this.errors.get(ev.error) ?? 0) >= 3) return "same error again";
    if (undo) return "undo and redo";
    const keys = (from: number) => new Set(last.filter((_, i) => i % 2 === from).map((e) => e.key));
    if (last.length === 6 && keys(0).size === 1 && keys(1).size === 1) return "ping-pong";
    return null;
  }
}

// Starting values; G1's effort sweep confirms each row.
export type Effort = "low" | "medium" | "high" | "xhigh";
export interface Route { model: string; effort: Effort }

export const ROUTES: Record<string, Route> = {
  readiness: { model: "claude-sonnet-5-5", effort: "low" },
  plan: { model: "claude-opus-5-5", effort: "medium" }, // the plan asks for "high" on fuzzy or cross-module tickets
  build: { model: "claude-opus-5-5", effort: "medium" }, // the default for every job not listed
  "build-hard": { model: "claude-opus-5-5", effort: "high" }, // a bug in existing code, many edge cases
  helper: { model: "claude-haiku-5-5", effort: "medium" }, // reading and search; returns file:line pointers
  qa: { model: "claude-sonnet-5-5", effort: "medium" },
  "ci-fix": { model: "claude-opus-5-5", effort: "low" }, // CI is the checker; re-run at medium if it fails
};
const LEVELS: Effort[] = ["low", "medium", "high", "xhigh"];
export const ROUTING_ENV = {
  CLAUDE_CODE_MAX_OUTPUT_TOKENS: "64000", // at 16K most long attempts were cut off
  CLAUDE_CODE_PROMPT_CACHE_TTL: "1h", // Nova waits on people; routines use 5m
};

export const routeFor = (job: string): Route => ROUTES[job] ?? ROUTES.build!;

/** A step whose checks failed is re-run once, one level higher, in the same session (warm cache). */
export const rerunOneLevelUp = async (session: NovaSession, step: Step, route: Route): Promise<Route> => {
  const higher = LEVELS[Math.min(LEVELS.indexOf(route.effort) + 1, LEVELS.length - 1)]!;
  await session.query.applyFlagSettings({ effortLevel: higher }); // from the next turn; check cache reads in the W6 spike
  await session.send(step.retryPrompt()); // streaming input: the same session, no restart
  return { model: route.model, effort: higher };
};

// No maxTurns, no maxBudgetUsd, no taskBudget: test/no-limits.test.ts fails if one appears.

const RUNGS = ["nudge", "replan", "think_harder", "fresh_start", "ask_person"] as const; // also the metric's rung label
const STEP_IN_AT = [6, 9, 12, 15, 18]; // tool events with no real progress; tuned from logged verdicts

/** Rungs 1-2: extra context returned by the watcher's PostToolUse hook. */
export const inTurnContext = (verdict: WatcherVerdict): string | undefined => {
  if (verdict.flatFor === STEP_IN_AT[0]) {
    return `Heads up: ${verdict.loopKind} (${verdict.evidence}). Try a different approach, or say what blocks you.`;
  }
  if (verdict.flatFor === STEP_IN_AT[1]) return "Step back: write a short new plan for this step before you do anything else.";
  return undefined;
};

/** Rungs 3-5: at a step boundary, after a checkpoint. Real progress resets the ladder. */
export const betweenTurns = async (run: Run, session: NovaSession, verdict: WatcherVerdict): Promise<void> => {
  if (verdict.flatFor === 0) {
    run.rung = 2;
    return;
  }
  const rung = RUNGS[run.rung];
  if (!rung || verdict.flatFor < STEP_IN_AT[run.rung]!) return;
  metrics.handoffs.add(1, { rung }); // ai_agents_watcher_handoffs_total{rung}
  if (rung === "think_harder") {
    run.route = await rerunOneLevelUp(session, run.step, run.route);
  } else if (rung === "fresh_start") {
    await checkpoint(run, run.step);
    await run.restartSession({ seed: await run.notes() }); // new context, same branch and notes
  } else if (rung === "ask_person") {
    await askHuman(run, `I'm stuck on '${run.step.title}': ${verdict.summary()}. What should I try?`);
  }
  run.rung += 1;
};

const SHADOW = (process.env.NOVA_BACKSTOP_MODE ?? "shadow") === "shadow"; // shadow for the first 4 weeks
const BACKSTOP_USD = Number(process.env.NOVA_BACKSTOP_USD ?? "200"); // far away; set from real data later
const CONTINUE: StepGate = { kind: "continue" };

export const afterStep = async (run: Run): Promise<StepGate> => {
  if (run.elapsedMs() > run.estimate.durationMs * run.nextCheckin) {
    const note = await run.askModel("In 3 short lines: what is taking time, and why is it worth it?");
    await run.broker.postProgress(`Check-in: I'm past my estimate of ${run.estimate.text}.\n${note}`);
    run.nextCheckin *= 2; // at 2x, 4x, 8x ... and keep going unless someone says stop
  }

  const spend = await run.gateway.spend(run.runId); // the gateway is the source of truth
  if (spend < BACKSTOP_USD) return CONTINUE;
  metrics.backstop.add(1, { mode: SHADOW ? "shadow" : "live" }); // ai_agents_backstop_would_pause_total{mode}
  if (SHADOW) {
    log.info("backstop would pause", { run: run.runId, spend_usd: spend });
    return CONTINUE;
  }
  await checkpoint(run, run.step); // nothing is lost; one tap resumes exactly here
  return { kind: "ask", question: "I've used more than the far-away budget for one ticket. Continue?" };
};

