Create src/watch-event.ts. It is a small stand-in for the harness's normalizer. It hashes inputs and outputs and masks numbers in errors. It marks checks, todos, first reads and file hashes. A recorded Edit carries its file hash as after_hash.

import { createHash } from "node:crypto";

// A recorded PostToolUse input: the fields the watcher reads.
export interface ToolInput { tool_name: string; tool_input: Record<string, unknown>; tool_response?: string; error?: string }
const hash = (s: string) => createHash("sha256").update(s).digest("hex").slice(0, 12);
const normalize = (s: string) => s.replace(/\d{4}-\d\d-\d\dT[\d:.]+Z?/g, "<time>").replace(/\/tmp\/\S+/g, "<tmp>");
const CHECK = /^(npm test|npx playwright test|npm run lint)/;
const seen = new Set<string>();

export class WatchEvent {
  constructor(readonly key: string, readonly error: string | null, readonly isCheck: boolean, readonly passed: boolean,
    readonly check: string, readonly todoCompleted: boolean, readonly firstRead: boolean, readonly file: string | null, readonly fileHash: string | null) {}
  static of(input: ToolInput): WatchEvent {
    const command = String(input.tool_input.command ?? "");
    const inputHash = hash(normalize(JSON.stringify(input.tool_input)));
    const outputHash = hash(normalize(input.tool_response ?? input.error ?? ""));
    const error = input.error ? input.error.split("\n")[0]!.replace(/\d+/g, "N") : null;
    const isCheck = input.tool_name === "Bash" && CHECK.test(command);
    const path = String(input.tool_input.file_path ?? "");
    const firstRead = input.tool_name === "Read" && !seen.has(path) && (seen.add(path), true);
    const todoCompleted = input.tool_name === "TodoWrite" && JSON.stringify(input.tool_input).includes('"completed"');
    const isEdit = input.tool_name === "Edit" || input.tool_name === "Write";
    return new WatchEvent(`${input.tool_name}:${inputHash}:${outputHash}`, error, isCheck, isCheck && !input.error,
      command, todoCompleted, firstRead, isEdit ? path : null, isEdit ? String(input.tool_input.after_hash ?? "") : null);
  }
  evidence(): string { return this.error ?? this.key; }
}

