import { WatchEvent, type ToolInput } from "./watch-event.js";

type HookCallback = (input: ToolInput) => Promise<object>;
export const state: { verdict?: { flatFor: number; loopKind: string | null; evidence: string } } = {};

export class Watcher {
  readonly events: WatchEvent[] = [];
  readonly errors = new Map<string, number>();
  readonly fileHashes = new Map<string, string[]>();
  readonly failing = new Set<string>();
  flatFor = 0;
  onTool: HookCallback = async (input) => {
    const ev = WatchEvent.of(input);
    this.events.push(ev);
    if (this.events.length > 200) this.events.shift();
    this.flatFor = this.progressed(ev) ? 0 : this.flatFor + 1;
    state.verdict = { flatFor: this.flatFor, loopKind: this.loopKind(ev), evidence: ev.evidence() };
    return {};
  };
  progressed(ev: WatchEvent): boolean {
    const fixed = ev.isCheck && ev.passed && this.failing.has(ev.check);
    if (ev.isCheck) this.failing[ev.passed ? "delete" : "add"](ev.check);
    return fixed || ev.todoCompleted || ev.firstRead;
  }
  loopKind(ev: WatchEvent): string | null {
    const last = this.events.slice(-6);
    if (ev.error) this.errors.set(ev.error, (this.errors.get(ev.error) ?? 0) + 1);
    const undo = this.rememberFile(ev);
    if (last.filter((e) => e.key === ev.key).length >= 3) return "same command, same result";
    if (ev.error && (this.errors.get(ev.error) ?? 0) >= 3) return "same error again";
    if (undo) return "undo and redo";
    const keys = (from: number) => new Set(last.filter((_, i) => i % 2 === from).map((e) => e.key));
    if (last.length === 6 && keys(0).size === 1 && keys(1).size === 1) return "ping-pong";
    return null;
  }
  rememberFile(ev: WatchEvent): boolean {
    if (!ev.file || !ev.fileHash) return false;
    const seen = this.fileHashes.get(ev.file) ?? [];
    const back = seen.slice(0, -1).includes(ev.fileHash);
    this.fileHashes.set(ev.file, [...seen, ev.fileHash]);
    return back;
  }
}

Create test/watcher.test.ts. replay feeds a recording through onTool and collects the verdicts.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { Watcher, state } from "../src/watcher.js";

const replay = async (name: string) => {
  const events = JSON.parse(readFileSync(new URL(`./events/${name}.json`, import.meta.url), "utf8"));
  const watcher = new Watcher();
  const verdicts = [];
  for (const input of events) {
    await watcher.onTool(input);
    verdicts.push(state.verdict!);
  }
  return verdicts;
};

test("a healthy test-driven loop is never flagged", async () => {
  const verdicts = await replay("healthy-tdd");
  assert.deepEqual(verdicts.map((v) => v.loopKind), Array(7).fill(null));
  assert.equal(verdicts.at(-1)!.flatFor, 0);
});

test("a flaky-test retry loop is flagged", async () => {
  const verdicts = await replay("flaky-retry");
  assert.equal(verdicts.at(-1)!.loopKind, "same command, same result");
  assert.equal(verdicts.at(-1)!.flatFor, 3);
});
